// each request takes about 1 second; they do not depend on each other
async function loadDashboard() {
  const results = [];
  for (const url of ["/api/sales", "/api/users", "/api/stock"]) {
    results.push(await fetch(url).then(r => r.json()));
  }
  return results;
}

